"use client";

import Link from "next/link";
import { useEffect, useRef, useState, useTransition, type FormEvent, type ReactNode } from "react";
import { AlertTriangle, ChevronRight, Download, FileCheck2, Filter, MoreHorizontal, Paperclip, Plus, ReceiptText, Search, WalletCards, X } from "lucide-react";
import { ExpenseAttachmentUploader } from "./expense-attachment-uploader";
import { expensePrimaryAction, formatPeso, statusLabel } from "@/lib/expenses";
import type { ExpenseWorkspaceData, ExpenseWorkspaceRow } from "@/lib/server/expenses-data";
import { cn } from "@/lib/utils";

type View = "all" | "needs_review" | "recurring" | "reimbursements";

export function ExpensesWorkspace({ initialData, currentUserId, initialFilters }: { initialData: ExpenseWorkspaceData; currentUserId: string | null; initialFilters: { view: string; q: string; status: string; project: string; receipt: string; special: string; reference: string } }) {
  const [data, setData] = useState(initialData);
  const [view, setView] = useState<View>(() => (["all", "needs_review", "recurring", "reimbursements"].includes(initialFilters.view) ? initialFilters.view as View : "all"));
  const [query, setQuery] = useState(initialFilters.q);
  const [status, setStatus] = useState(initialFilters.status);
  const [project, setProject] = useState(initialFilters.project);
  const [receipt, setReceipt] = useState(initialFilters.receipt);
  const [special, setSpecial] = useState(initialFilters.special);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(() => initialData.rows.find((row) => row.reference === initialFilters.reference)?.id ?? null);
  const [formOpen, setFormOpen] = useState(false);
  const [reimbursementMode, setReimbursementMode] = useState(false);
  const [recurringOpen, setRecurringOpen] = useState(false);
  const [correcting, setCorrecting] = useState<ExpenseWorkspaceRow | null>(null);
  const [message, setMessage] = useState("");
  const [, startTransition] = useTransition();
  const returnFocus = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const params = new URLSearchParams();
    if (view !== "all") params.set("view", view); if (query) params.set("q", query); if (status) params.set("status", status); if (project) params.set("project", project); if (receipt) params.set("receipt", receipt); if (special) params.set("filter", special);
    const selected = data.rows.find((row) => row.id === selectedId); if (selected) params.set("ref", selected.reference);
    window.history.replaceState(null, "", `${window.location.pathname}${params.size ? `?${params}` : ""}`);
  }, [data.rows, project, query, receipt, selectedId, special, status, view]);

  const rows = data.rows.filter((row) => {
    const searchable = [row.vendor, row.reference, row.description, row.projectReference, row.projectTitle, row.submitter, row.receiptNumber, row.invoiceNumber, row.paymentSource].filter(Boolean).join(" ").toLowerCase();
    if (query && !searchable.includes(query.toLowerCase())) return false;
    if (view === "needs_review" && !["submitted", "needs_review"].includes(row.status)) return false;
    if (view === "recurring" && !row.recurringTemplateId) return false;
    if (view === "reimbursements" && row.reimbursementState === "not_applicable") return false;
    if (status && row.status !== status) return false;
    if (project && row.projectId !== project) return false;
    if (receipt && row.receiptStatus !== receipt) return false;
    if (special === "owner_funded" && !row.ownerFunded) return false;
    if (special === "missing_receipt" && row.receiptStatus !== "missing") return false;
    if (special === "project" && !row.projectId) return false;
    if (special === "overhead" && row.projectId) return false;
    if (special === "duplicate" && !row.duplicateSuspected) return false;
    return true;
  });
  const selected = data.rows.find((row) => row.id === selectedId) ?? null;

  async function refresh() { const response = await fetch("/api/expenses", { cache: "no-store" }); if (response.ok) setData(await response.json() as ExpenseWorkspaceData); }
  function openDetails(row: ExpenseWorkspaceRow, target: HTMLElement) { returnFocus.current = target; setSelectedId(row.id); }
  function closeDetails() { setSelectedId(null); requestAnimationFrame(() => returnFocus.current?.focus()); }
  function openForm(reimbursement: boolean) { setReimbursementMode(reimbursement); setFormOpen(true); }

  return <div className="min-w-0 pb-14">
    <header className="app-page border-b border-[var(--color-border)] bg-[var(--color-surface)] px-4 pb-6 pt-6 sm:px-6 lg:px-8">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><h1 className="font-display text-[clamp(2rem,4vw,2.5rem)] font-semibold tracking-[-.03em]">Expenses</h1><p className="mt-1 text-[15px] text-[var(--color-text-secondary)]">Record, approve and allocate every studio cost.</p></div><div className="flex flex-wrap gap-2">{data.canSubmitReimbursement ? <button onClick={() => openForm(true)} className="min-h-11 rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] px-4 text-sm font-semibold text-[#FF5300] hover:bg-[var(--color-kahel-50)]">Request reimbursement</button> : null}{data.canManage ? <button onClick={() => openForm(false)} className="inline-flex min-h-11 items-center gap-2 rounded-control bg-[#FF5300] px-4 text-sm font-semibold text-white hover:bg-[#E64B00]"><Plus className="h-4 w-4" /> Record expense</button> : null}</div></div>
      <div className="mt-6 grid gap-3 md:grid-cols-3"><Metric icon={<ReceiptText />} title="This month" value={formatPeso(data.summary.thisMonth)} detail="Approved, scheduled or paid expenses" sub={data.summary.previousMonth === null ? "Previous-month comparison unavailable" : `${comparison(data.summary.thisMonth, data.summary.previousMonth)} vs previous month`} /><Metric icon={<FileCheck2 />} title="Needs review" value={String(data.summary.needsReviewCount)} detail={`${formatPeso(data.summary.needsReviewAmount)} awaiting action`} tone="warning" /><Metric icon={<WalletCards />} title="Owner-funded" value={formatPeso(data.summary.ownerOutstanding)} detail={`${formatPeso(data.summary.ownerRepaid)} repaid of ${formatPeso(data.summary.ownerAdvanced)}`} tone="info" /></div>
    </header>

    <section className="px-4 pt-5 sm:px-6 lg:px-8" aria-label="Expense controls">
      <div className="flex flex-wrap gap-2">{(["all", "needs_review", "recurring", "reimbursements"] as View[]).map((item) => <button key={item} onClick={() => startTransition(() => setView(item))} aria-pressed={view === item} className={cn("min-h-11 rounded-control border px-3.5 text-sm font-semibold", view === item ? "border-[#FF5300] bg-[var(--color-kahel-50)] text-[var(--color-kahel-700)]" : "border-[var(--color-border)] bg-[var(--color-surface)] text-[var(--color-text-secondary)] hover:bg-[var(--color-surface-muted)]")}>{statusLabel(item)}</button>)}<button onClick={() => setFiltersOpen((value) => !value)} aria-expanded={filtersOpen} className="inline-flex min-h-11 items-center gap-2 rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] px-3.5 text-sm font-semibold"><Filter className="h-4 w-4" /> Filters</button>{data.canManage ? <Link href="/api/expenses/export" className="ml-auto inline-flex min-h-11 items-center gap-2 rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] px-3.5 text-sm font-semibold"><Download className="h-4 w-4" /> Export</Link> : null}</div>
      <label className="mt-3 flex min-h-11 items-center gap-2 rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] px-3"><Search className="h-4 w-4 text-[var(--color-text-muted)]" /><span className="sr-only">Search expenses</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search vendor, reference, project, submitter or receipt" className="min-w-0 flex-1 bg-transparent text-sm outline-none" /></label>
      {filtersOpen ? <div className="mt-3 grid gap-3 rounded-card border border-[var(--color-border)] bg-[var(--color-surface)] p-4 sm:grid-cols-2 lg:grid-cols-4"><Select label="Status" value={status} onChange={setStatus} options={["", "draft", "submitted", "needs_review", "changes_requested", "approved", "scheduled_for_payment", "paid", "rejected", "voided"].map(option)} /><Select label="Project" value={project} onChange={setProject} options={[{ value: "", label: "Any project" }, ...data.projects.map((item) => ({ value: item.id, label: `${item.reference} · ${item.title}` }))]} /><Select label="Receipt state" value={receipt} onChange={setReceipt} options={["", "missing", "attached", "under_review", "verified", "invalid", "not_required"].map(option)} /><Select label="Expense type" value={special} onChange={setSpecial} options={[{ value: "", label: "Any type" }, { value: "owner_funded", label: "Owner-funded" }, { value: "missing_receipt", label: "Missing receipt" }, { value: "project", label: "Project expenses" }, { value: "overhead", label: "Studio overhead" }, { value: "duplicate", label: "Duplicate suspected" }]} /><button onClick={() => { setStatus(""); setProject(""); setReceipt(""); setSpecial(""); }} className="min-h-11 rounded-control border border-[var(--color-border)] px-3 text-sm font-semibold">Clear filters</button></div> : null}
    </section>

    <section className="px-4 pt-4 sm:px-6 lg:px-8" aria-live="polite">
      {message ? <div className="mb-3 rounded-control bg-[var(--color-info-bg)] px-3 py-2 text-sm text-[var(--color-info-text)]">{message}</div> : null}
      <div className="hidden overflow-x-auto rounded-card border border-[var(--color-border)] bg-[var(--color-surface)] md:block"><table className="w-full min-w-[1100px] border-separate border-spacing-0"><thead><tr className="bg-[var(--color-canvas)] text-left text-[11px] font-semibold uppercase tracking-[.04em] text-[var(--color-text-secondary)]"><Th>Date</Th><Th>Vendor / reference</Th><Th>Category / description</Th><Th>Allocated to</Th><Th>Paid by</Th><Th>Receipt</Th><Th>Status</Th><Th right>Amount</Th><Th right>Actions</Th></tr></thead><tbody>{rows.map((row) => <tr key={row.id} tabIndex={0} aria-selected={selectedId === row.id} onClick={(event) => openDetails(row, event.currentTarget)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); openDetails(row, event.currentTarget); } }} className={cn("cursor-pointer outline-none hover:bg-[var(--color-kahel-50)] focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-[#FF5300]", selectedId === row.id && "bg-[var(--color-kahel-50)]")}><Td mono>{manilaDate(row.transactionDate)}</Td><Td><strong>{row.vendor}</strong><small>{row.reference} · {row.attachments.length ? "Receipt attached" : "No attachment"}</small></Td><Td><strong>{row.category}</strong><small>{row.description}</small></Td><Td><strong>{row.allocationLabel}</strong><small>{row.projectTitle ?? "Internal studio cost"}</small></Td><Td><strong>{row.paymentSource ?? statusLabel(row.paidByType)}</strong><small>{row.paymentMethod ? statusLabel(row.paymentMethod) : "Not recorded"}</small></Td><Td><Badge tone={receiptTone(row.receiptStatus)}>{statusLabel(row.receiptStatus)}</Badge></Td><Td><Badge tone={statusTone(row.status)}>{statusLabel(row.status)}</Badge>{row.duplicateSuspected ? <small className="text-[var(--color-warning-text)]">Duplicate suspected</small> : null}</Td><Td right><strong className="font-display tabular-nums">{formatPeso(row.total)}</strong></Td><Td right><span className="inline-flex min-h-11 items-center gap-1 text-sm font-semibold">{expensePrimaryAction(row.status, row.reimbursementState)} <MoreHorizontal className="h-4 w-4" /></span></Td></tr>)}</tbody></table>{!rows.length ? <Empty filtered={Boolean(query || status || project || receipt || special)} /> : null}</div>
      <div className="grid gap-3 md:hidden">{rows.map((row) => <button key={row.id} onClick={(event) => openDetails(row, event.currentTarget)} className="min-h-11 rounded-card border border-[var(--color-border)] bg-[var(--color-surface)] p-4 text-left"><div className="flex items-start justify-between gap-3"><div><strong className="block font-display text-lg">{row.vendor}</strong><span className="mt-1 block text-xs tabular-nums text-[var(--color-text-secondary)]">{row.reference} · {manilaDate(row.transactionDate)}</span></div><strong className="font-display tabular-nums">{formatPeso(row.total)}</strong></div><p className="mt-3 line-clamp-2 text-sm text-[var(--color-text-secondary)]">{row.description}</p><div className="mt-3 flex flex-wrap items-center gap-2"><Badge tone={statusTone(row.status)}>{statusLabel(row.status)}</Badge><Badge tone={receiptTone(row.receiptStatus)}>{statusLabel(row.receiptStatus)}</Badge><span className="ml-auto text-xs font-semibold">{row.allocationLabel} <ChevronRight className="inline h-3 w-3" /></span></div></button>)}{!rows.length ? <Empty filtered={Boolean(query || status || project || receipt || special)} /> : null}</div>
      {view === "recurring" ? <div className="mt-5 rounded-card border border-[var(--color-border)] bg-[var(--color-surface)] p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-display text-lg font-semibold">Recurring commitments</h2><p className="mt-1 text-sm text-[var(--color-text-secondary)]">Templates are obligations, not paid expenses. Individual instances enter review separately.</p></div>{data.canManage ? <button onClick={() => setRecurringOpen(true)} className="min-h-11 rounded-control border border-[var(--color-border)] px-3 text-sm font-semibold">New recurring cost</button> : null}</div><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{data.recurring.map((item) => <article key={item.id} className="rounded-control border border-[var(--color-border)] p-4"><div className="flex items-start justify-between"><strong>{item.vendor}</strong><Badge tone={item.state === "active" ? "success" : "warning"}>{statusLabel(item.state)}</Badge></div><p className="mt-3 font-display text-xl font-semibold tabular-nums">{formatPeso(item.amount)}</p><p className="mt-1 text-xs text-[var(--color-text-secondary)]">{statusLabel(item.frequency)} · Due {manilaDate(item.nextDue)}</p>{data.canManage && item.state === "active" ? <button onClick={async () => { const response = await fetch("/api/expenses/recurring", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "generate", templateId: item.id }) }); if (response.ok) { await refresh(); setMessage("Recurring expense draft generated."); } else setMessage(((await response.json().catch(() => ({}))) as { error?: string }).error ?? "Unable to generate recurring expense."); }} className="mt-3 min-h-11 w-full rounded-control border border-[var(--color-border)] text-sm font-semibold">Generate due expense</button> : null}</article>)}{!data.recurring.length ? <p className="text-sm text-[var(--color-text-secondary)]">No recurring commitments configured.</p> : null}</div></div> : null}
    </section>

    {selected ? <ExpenseDrawer row={selected} rows={data.rows} paymentSources={data.paymentSources} canManage={data.canManage} currentUserId={currentUserId} close={closeDetails} correct={() => { setCorrecting(selected); closeDetails(); }} refresh={refresh} notify={setMessage} /> : null}
    {formOpen ? <ExpenseForm data={data} reimbursement={reimbursementMode} currentUserId={currentUserId} close={() => setFormOpen(false)} complete={async (expenseId) => { setFormOpen(false); await refresh(); setSelectedId(expenseId); setMessage(reimbursementMode ? "Reimbursement submitted for review." : "Expense saved."); }} /> : null}
    {recurringOpen ? <RecurringExpenseForm data={data} close={() => setRecurringOpen(false)} complete={async () => { setRecurringOpen(false); await refresh(); setMessage("Recurring commitment created."); }} /> : null}
    {correcting ? <ExpenseCorrectionForm row={correcting} data={data} close={() => setCorrecting(null)} complete={async () => { setCorrecting(null); await refresh(); setMessage("Expense corrected and resubmitted."); }} /> : null}
  </div>;
}

function RecurringExpenseForm({ data, close, complete }: { data: ExpenseWorkspaceData; close: () => void; complete: () => Promise<void> }) {
  const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); const payload = { ...Object.fromEntries(new FormData(event.currentTarget).entries()), action: "create" }; const response = await fetch("/api/expenses/recurring", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); setBusy(false); if (!response.ok) { setError(((await response.json().catch(() => ({}))) as { error?: string }).error ?? "Unable to create recurring commitment."); return; } await complete(); }
  return <><button aria-label="Close recurring expense form" onClick={close} className="fixed inset-0 z-40 bg-black/35" /><aside role="dialog" aria-modal="true" aria-labelledby="recurring-title" className="fixed inset-y-0 right-0 z-50 w-full max-w-xl overflow-y-auto border-l border-[var(--color-border)] bg-[var(--color-surface)] p-5 shadow-2xl"><div className="flex justify-between"><div><h2 id="recurring-title" className="font-display text-2xl font-semibold">Recurring commitment</h2><p className="mt-1 text-sm text-[var(--color-text-secondary)]">Creates a template only. Generated expenses require review.</p></div><button onClick={close} aria-label="Close form" className="grid min-h-11 min-w-11 place-items-center"><X className="h-4 w-4" /></button></div><form onSubmit={submit} className="mt-5 grid gap-4 sm:grid-cols-2"><Input label="Vendor" name="vendor" required /><SelectNative label="Category" name="categoryId" required options={data.categories.map((item) => ({ value: item.id, label: item.name }))} /><Input label="Expected amount (PHP)" name="amount" required /><SelectNative label="Frequency" name="frequency" required options={["weekly", "monthly", "quarterly", "yearly"].map((value) => ({ value, label: statusLabel(value) }))} /><Input label="Start date" name="startDate" type="date" required /><Input label="Next due date" name="nextDueDate" type="date" required /><Input label="Optional end date" name="endDate" type="date" /><Input label="Reminder days" name="reminderDays" type="number" min="0" max="90" defaultValue="3" /><SelectNative label="Payment account" name="paymentSourceId" options={data.paymentSources.filter((source) => source.sourceType === "studio_account").map((source) => ({ value: source.id, label: source.name }))} /><SelectNative label="Project allocation" name="projectId" options={data.projects.map((project) => ({ value: project.id, label: `${project.reference} · ${project.title}` }))} />{error ? <p role="alert" className="sm:col-span-2 text-sm text-[var(--color-danger-text)]">{error}</p> : null}<button disabled={busy} className="min-h-11 rounded-control bg-[#FF5300] px-4 text-sm font-semibold text-white sm:col-span-2">Create commitment</button></form></aside></>;
}

function ExpenseDrawer({ row, rows, paymentSources, canManage, currentUserId, close, correct, refresh, notify }: { row: ExpenseWorkspaceRow; rows: ExpenseWorkspaceRow[]; paymentSources: ExpenseWorkspaceData["paymentSources"]; canManage: boolean; currentUserId: string | null; close: () => void; correct: () => void; refresh: () => Promise<void>; notify: (value: string) => void }) {
  const panel = useRef<HTMLElement>(null);
  const [busy, setBusy] = useState(false);
  const [reason, setReason] = useState("");
  useEffect(() => { panel.current?.focus(); const key = (event: KeyboardEvent) => event.key === "Escape" && close(); document.addEventListener("keydown", key); return () => document.removeEventListener("keydown", key); }, [close]);
  async function transition(action: string) { setBusy(true); const response = await fetch(`/api/expenses/${row.id}/transition`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, expectedVersion: row.version, reason }) }); await finishAction(response, action); }
  async function finishAction(response: Response, action: string) { const result = await response.json().catch(() => ({})) as { error?: string; stale?: boolean }; setBusy(false); if (!response.ok) { notify(result.error ?? "Unable to update expense."); if (result.stale) await refresh(); return; } notify(`Expense ${statusLabel(action)}.`); setReason(""); await refresh(); }
  const canReview = canManage && ["submitted", "needs_review"].includes(row.status) && row.submitterId !== currentUserId;
  const canCorrect = ["draft", "changes_requested"].includes(row.status) && row.submitterId === currentUserId;
  return <>
    <button aria-label="Close expense details" onClick={close} className="fixed inset-0 z-40 bg-black/35" />
    {canCorrect ? <button onClick={correct} className="fixed bottom-5 right-5 z-[60] min-h-11 rounded-control bg-[#FF5300] px-4 text-sm font-semibold text-white shadow-lg">{row.status === "draft" ? "Continue expense" : "Correct expense"}</button> : null}
    <aside ref={panel} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="expense-detail-title" className="fixed inset-y-0 right-0 z-50 flex w-full max-w-3xl flex-col border-l border-[var(--color-border)] bg-[var(--color-surface)] shadow-2xl outline-none">
      <header className="border-b border-[var(--color-border)] p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold tabular-nums text-[var(--color-text-muted)]">{row.reference}</p><h2 id="expense-detail-title" className="mt-1 font-display text-2xl font-semibold">{row.vendor}</h2><div className="mt-2 flex flex-wrap gap-2"><Badge tone={statusTone(row.status)}>{statusLabel(row.status)}</Badge><Badge tone={receiptTone(row.receiptStatus)}>Receipt {statusLabel(row.receiptStatus)}</Badge>{row.ownerAdvanceStatus ? <Badge tone="info">Owner advance {statusLabel(row.ownerAdvanceStatus)}</Badge> : null}{row.duplicateSuspected ? <Badge tone="warning">Duplicate suspected</Badge> : null}</div></div><button onClick={close} aria-label="Close details" className="grid min-h-11 min-w-11 place-items-center rounded-control border border-[var(--color-border)]"><X className="h-4 w-4" /></button></div><div className="mt-4 flex items-center justify-between rounded-card bg-[var(--color-canvas)] p-4"><div><p className="text-xs font-semibold uppercase text-[var(--color-text-secondary)]">Expense total</p><p className="mt-1 text-xs text-[var(--color-text-muted)]">Transaction {manilaDate(row.transactionDate)}</p></div><strong className="font-display text-3xl tabular-nums">{formatPeso(row.total)}</strong></div></header>
      <div className="min-h-0 flex-1 overflow-y-auto p-5"><div className="grid gap-3 sm:grid-cols-2"><Detail label="Category" value={row.category} /><Detail label="Allocation" value={row.allocationLabel} /><Detail label="Paid by / account" value={row.paymentSource ?? statusLabel(row.paidByType)} /><Detail label="Payment method" value={row.paymentMethod ? statusLabel(row.paymentMethod) : "Not recorded"} /><Detail label="Submission date" value={dateTime(row.submittedAt)} /><Detail label="Approval date" value={dateTime(row.approvedAt)} /><Detail label="Submitter" value={row.submitter} /><Detail label="Reviewer" value={row.reviewer ?? "Not reviewed"} /></div>
        <Section title="Description"><p className="text-sm text-[var(--color-text-secondary)]">{row.description}</p>{row.internalNote ? <p className="mt-2 rounded-control bg-[var(--color-canvas)] p-3 text-sm">Internal note: {row.internalNote}</p> : null}</Section>
        <Section title="Allocation breakdown">{row.allocations.map((allocation) => <div key={allocation.id} className="flex justify-between gap-3 border-b border-[var(--color-border)] py-2 text-sm last:border-0"><span>{statusLabel(allocation.label)}</span><strong className="tabular-nums">{formatPeso(allocation.amount)}</strong></div>)}</Section>
        <Section title="Receipts and documents"><div className="space-y-2">{row.attachments.map((attachment) => <a key={attachment.id} href={`/api/expenses/${row.id}/attachments/${attachment.id}`} className="flex min-h-11 items-center gap-2 rounded-control border border-[var(--color-border)] px-3 text-sm font-semibold"><Paperclip className="h-4 w-4" /><span className="min-w-0 flex-1 truncate">{attachment.filename}</span><Badge tone={receiptTone(attachment.status)}>{statusLabel(attachment.status)}</Badge></a>)}{!row.attachments.length ? <p className="text-sm text-[var(--color-text-secondary)]">No documents attached.{row.receiptException ? ` ${row.receiptException}` : ""}</p> : null}</div>{!["rejected", "voided", "paid"].includes(row.status) ? <div className="mt-3"><ExpenseAttachmentUploader expenseId={row.id} onComplete={() => void refresh()} /></div> : null}</Section>
        {row.ownerFunded ? <Section title="Owner advance"><div className="grid gap-2 sm:grid-cols-3"><Detail label="Advanced" value={formatPeso(row.total)} /><Detail label="Repaid" value={formatPeso(row.amountRepaid)} /><Detail label="Outstanding" value={formatPeso(row.total - row.amountRepaid)} /></div></Section> : null}
        <Section title="Activity"><ol className="space-y-3">{row.activity.map((item) => <li key={item.id} className="border-l-2 border-[var(--color-border)] pl-3"><p className="text-sm font-semibold">{statusLabel(item.action)}</p><p className="text-xs text-[var(--color-text-secondary)]">{item.actor} · {dateTime(item.at)}</p>{item.reason ? <p className="mt-1 text-sm">{item.reason}</p> : null}</li>)}</ol></Section>
      </div>
      <footer className="border-t border-[var(--color-border)] p-5"><p className="mb-3 text-sm font-semibold">{expensePrimaryAction(row.status, row.reimbursementState)}</p>{canReview ? <div className="grid gap-2"><label className="text-xs font-semibold text-[var(--color-text-secondary)]">Reviewer note<input value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Required for changes or rejection" className="mt-1 min-h-11 w-full rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] px-3 text-sm" /></label><div className="grid grid-cols-3 gap-2"><button disabled={busy} onClick={() => void transition("approve")} className="min-h-11 rounded-control bg-[var(--color-success)] px-3 text-sm font-semibold text-white">Approve</button><button disabled={busy || !reason.trim()} onClick={() => void transition("request_changes")} className="min-h-11 rounded-control bg-[var(--color-warning-bg)] px-3 text-sm font-semibold text-[var(--color-warning-text)]">Request changes</button><button disabled={busy || !reason.trim()} onClick={() => void transition("reject")} className="min-h-11 rounded-control border border-[var(--color-danger)] px-3 text-sm font-semibold text-[var(--color-danger-text)]">Reject</button></div></div> : null}<ExpenseFinancialActions row={row} rows={rows} paymentSources={paymentSources} canManage={canManage} busy={busy} setBusy={setBusy} finish={finishAction} />{row.projectReference ? <Link href={`/projects/${row.projectReference}`} className="mt-2 inline-flex min-h-11 items-center rounded-control border border-[var(--color-border)] px-3 text-sm font-semibold">View project</Link> : null}</footer>
    </aside>
  </>;
}

function ExpenseFinancialActions({ row, rows, paymentSources, canManage, busy, setBusy, finish }: { row: ExpenseWorkspaceRow; rows: ExpenseWorkspaceRow[]; paymentSources: ExpenseWorkspaceData["paymentSources"]; canManage: boolean; busy: boolean; setBusy: (value: boolean) => void; finish: (response: Response, action: string) => Promise<void> }) {
  const [open, setOpen] = useState<"payment" | "repayment" | "duplicate" | null>(null);
  const [key] = useState(() => crypto.randomUUID());
  if (!canManage) return null;
  async function submit(event: FormEvent<HTMLFormElement>, endpoint: string, action: string) { event.preventDefault(); setBusy(true); const payload = { ...Object.fromEntries(new FormData(event.currentTarget).entries()), action, expectedVersion: row.version, idempotencyKey: key }; const response = await fetch(endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); await finish(response, action); }
  if (row.status === "approved" && row.reimbursementState === "approved") return <button disabled={busy} onClick={async () => { setBusy(true); await finish(await fetch(`/api/expenses/${row.id}/reimbursement`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "schedule", expectedVersion: row.version }) }), "reimbursement scheduled"); }} className="min-h-11 rounded-control bg-[#FF5300] px-4 text-sm font-semibold text-white">Schedule payment</button>;
  const activeForm = row.status === "scheduled_for_payment" ? "payment" : open;
  if (row.ownerAdvanceStatus && ["outstanding", "partially_repaid"].includes(row.ownerAdvanceStatus) && open === null) return <button onClick={() => setOpen("repayment")} className="min-h-11 rounded-control border border-[var(--color-border)] px-3 text-sm font-semibold">Record owner repayment</button>;
  if (row.duplicateSuspected && open === null) return <button onClick={() => setOpen("duplicate")} className="min-h-11 rounded-control bg-[var(--color-warning-bg)] px-3 text-sm font-semibold text-[var(--color-warning-text)]">Resolve duplicate</button>;
  if (!activeForm) return null;
  const studioSources = activeForm === "payment" || activeForm === "repayment";
  return <form onSubmit={(event) => void submit(event, activeForm === "payment" ? `/api/expenses/${row.id}/reimbursement` : activeForm === "repayment" ? `/api/expenses/${row.id}/owner-repayment` : `/api/expenses/${row.id}/duplicate`, activeForm === "payment" ? "pay" : activeForm === "repayment" ? "repayment" : String((event.nativeEvent as SubmitEvent).submitter?.getAttribute("data-action") ?? "dismiss"))} className="mt-2 grid gap-2 rounded-card bg-[var(--color-canvas)] p-3">{activeForm === "repayment" ? <Input label="Repayment amount (PHP)" name="amount" defaultValue={((row.total - row.amountRepaid) / 100).toFixed(2)} required /> : null}{studioSources ? <><SelectNative label="Studio payment account" name="paymentSourceId" required options={paymentSources.filter((source) => source.sourceType === "studio_account").map((source) => ({ value: source.id, label: source.name }))} /><Input label="Transaction reference" name="transactionReference" required /><Input label="Date" name="paidAt" type="datetime-local" required /></> : <><SelectNative label="Canonical expense" name="duplicateOf" options={rows.filter((candidate) => candidate.id !== row.id && !candidate.duplicateOf).map((candidate) => ({ value: candidate.id, label: `${candidate.reference} · ${candidate.vendor} · ${formatPeso(candidate.total)}` }))} /><Input label="Resolution reason" name="reason" required /></>}<div className="flex gap-2">{activeForm === "duplicate" ? <><button data-action="dismiss" disabled={busy} className="min-h-11 rounded-control border border-[var(--color-border)] px-3 text-sm font-semibold">Not a duplicate</button><button data-action="confirm" disabled={busy} className="min-h-11 rounded-control bg-[var(--color-danger)] px-3 text-sm font-semibold text-white">Mark duplicate</button></> : <button disabled={busy} className="min-h-11 rounded-control bg-[#FF5300] px-3 text-sm font-semibold text-white">Confirm</button>}{activeForm !== "payment" ? <button type="button" onClick={() => setOpen(null)} className="min-h-11 rounded-control border border-[var(--color-border)] px-3 text-sm font-semibold">Cancel</button> : null}</div></form>;
}

function ExpenseCorrectionForm({ row, data, close, complete }: { row: ExpenseWorkspaceRow; data: ExpenseWorkspaceData; close: () => void; complete: () => Promise<void> }) {
  const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); const form = new FormData(event.currentTarget); const payload = { ...Object.fromEntries(form.entries()), expectedVersion: row.version, submit: true, allocations: row.allocations.map((allocation) => ({ allocationType: allocation.type, projectId: allocation.projectId, amount: (allocation.amount / 100).toFixed(2) })) }; const response = await fetch(`/api/expenses/${row.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); setBusy(false); if (!response.ok) { setError(((await response.json().catch(() => ({}))) as { error?: string }).error ?? "Unable to correct expense."); return; } await complete(); }
  return <><button aria-label="Close correction form" onClick={close} className="fixed inset-0 z-40 bg-black/35" /><aside role="dialog" aria-modal="true" aria-labelledby="correction-title" className="fixed inset-y-0 right-0 z-50 w-full max-w-xl overflow-y-auto border-l border-[var(--color-border)] bg-[var(--color-surface)] p-5 shadow-2xl"><div className="flex justify-between"><div><h2 id="correction-title" className="font-display text-2xl font-semibold">Correct expense</h2><p className="mt-1 text-sm text-[var(--color-text-secondary)]">Updates the same record and preserves its prior submission.</p></div><button onClick={close} aria-label="Close form" className="grid min-h-11 min-w-11 place-items-center"><X className="h-4 w-4" /></button></div><form onSubmit={submit} className="mt-5 grid gap-4 sm:grid-cols-2"><Input label="Transaction date" name="transactionDate" type="date" defaultValue={row.transactionDate} required /><Input label="Vendor" name="vendor" defaultValue={row.vendor} required /><SelectNative label="Category" name="categoryId" required value={row.categoryId} options={data.categories.map((category) => ({ value: category.id, label: category.name }))} /><Input label="Amount (PHP)" name="amount" defaultValue={(row.subtotal / 100).toFixed(2)} required /><Input label="Tax amount (PHP)" name="taxAmount" defaultValue={(row.tax / 100).toFixed(2)} /><SelectNative label="Receipt state" name="receiptStatus" required value={row.receiptStatus} options={["missing", "attached", "under_review", "verified", "invalid", "not_required"].map((value) => ({ value, label: statusLabel(value) }))} /><label className="grid gap-1 text-xs font-semibold sm:col-span-2"><span>Description</span><textarea name="description" rows={3} defaultValue={row.description} className="rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] p-3 text-sm" required /></label><Input label="Missing receipt explanation" name="receiptException" defaultValue={row.receiptException ?? ""} /><Input label="Internal note" name="internalNote" defaultValue={row.internalNote ?? ""} />{error ? <p role="alert" className="text-sm text-[var(--color-danger-text)] sm:col-span-2">{error}</p> : null}<button disabled={busy} className="min-h-11 rounded-control bg-[#FF5300] px-4 text-sm font-semibold text-white sm:col-span-2">Correct and resubmit</button></form></aside></>;
}

function ExpenseForm({ data, reimbursement, currentUserId, close, complete }: { data: ExpenseWorkspaceData; reimbursement: boolean; currentUserId: string | null; close: () => void; complete: (id: string) => Promise<void> }) {
  const panel = useRef<HTMLElement>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [ownerFunded, setOwnerFunded] = useState(false); const [allocations, setAllocations] = useState([{ id: crypto.randomUUID(), type: "studio_overhead", destinationId: "", amount: "" }]);
  useEffect(() => panel.current?.focus(), []);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(""); const form = new FormData(event.currentTarget); const payload = Object.fromEntries(form.entries()) as Record<string, unknown>; payload.idempotencyKey = crypto.randomUUID(); payload.submit = (event.nativeEvent as SubmitEvent).submitter?.getAttribute("data-submit") === "true" || reimbursement; payload.reimbursable = reimbursement; payload.ownerFunded = ownerFunded; payload.paidByUserId = reimbursement ? currentUserId : ownerFunded ? payload.paidByUserId : null; payload.allocations = allocations.map((allocation) => ({ allocationType: allocation.type, projectId: allocation.type === "project" ? allocation.destinationId : null, equipmentId: allocation.type === "inventory_asset" ? allocation.destinationId : null, maintenanceRecordId: allocation.type === "maintenance" ? allocation.destinationId : null, amount: allocation.amount || payload.amount })); const response = await fetch("/api/expenses", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const result = await response.json().catch(() => ({})) as { expense?: { id: string }; error?: string }; setBusy(false); if (!response.ok || !result.expense) { setError(result.error ?? "Unable to save expense."); return; } await complete(result.expense.id); }
  return <><button aria-label="Close expense form" onClick={close} className="fixed inset-0 z-40 bg-black/35" /><aside ref={panel} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="expense-form-title" className="fixed inset-y-0 right-0 z-50 w-full max-w-2xl overflow-y-auto border-l border-[var(--color-border)] bg-[var(--color-surface)] shadow-2xl outline-none"><form onSubmit={submit}><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[var(--color-border)] bg-[var(--color-surface)] p-5"><div><h2 id="expense-form-title" className="font-display text-2xl font-semibold">{reimbursement ? "Request reimbursement" : "Record expense"}</h2><p className="mt-1 text-sm text-[var(--color-text-secondary)]">{reimbursement ? "Record a studio cost paid personally by you." : "Create the canonical record for a studio cost."}</p></div><button type="button" onClick={close} aria-label="Close form" className="grid min-h-11 min-w-11 place-items-center rounded-control border border-[var(--color-border)]"><X className="h-4 w-4" /></button></header><div className="grid gap-4 p-5 sm:grid-cols-2"><Input label="Transaction date" name="transactionDate" type="date" required /><Input label="Vendor" name="vendor" placeholder="Existing or informal vendor" required /><SelectNative label="Category" name="categoryId" required options={data.categories.map((item) => ({ value: item.id, label: item.name }))} /><Input label="Amount (PHP)" name="amount" inputMode="decimal" placeholder="0.00" required /><Input label="Tax amount, if tracked (PHP)" name="taxAmount" inputMode="decimal" placeholder="0.00" /><SelectNative label="Payment account" name="paymentSourceId" options={data.paymentSources.map((item) => ({ value: item.id, label: item.name }))} /><label className="grid gap-1 text-xs font-semibold text-[var(--color-text-secondary)] sm:col-span-2"><span>Description</span><textarea name="description" required rows={3} className="rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] p-3 text-sm text-[var(--color-text-primary)]" /></label><div className="sm:col-span-2"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-[var(--color-text-secondary)]">Allocations</span><button type="button" onClick={() => setAllocations((current) => [...current, { id: crypto.randomUUID(), type: "project", destinationId: "", amount: "" }])} className="min-h-11 text-sm font-semibold text-[var(--color-kahel-700)]">Add split</button></div>{allocations.map((item, index) => <div key={item.id} className="mt-2 grid gap-2 rounded-control border border-[var(--color-border)] p-3 sm:grid-cols-[1fr_1.4fr_1fr_auto]"><SelectNative label="Destination" name={`allocationType-${item.id}`} value={item.type} onChange={(value) => setAllocations((current) => current.map((allocation) => allocation.id === item.id ? { ...allocation, type: value, destinationId: "" } : allocation))} options={[{ value: "studio_overhead", label: "Studio overhead" }, { value: "project", label: "Project" }, { value: "inventory_asset", label: "Equipment asset" }, { value: "maintenance", label: "Maintenance record" }]} />{item.type === "project" ? <SelectNative label="Project" name={`destination-${item.id}`} value={item.destinationId} onChange={(value) => setAllocations((current) => current.map((allocation) => allocation.id === item.id ? { ...allocation, destinationId: value } : allocation))} required options={data.projects.map((project) => ({ value: project.id, label: project.reference }))} /> : item.type === "inventory_asset" ? <SelectNative label="Equipment" name={`destination-${item.id}`} value={item.destinationId} onChange={(value) => setAllocations((current) => current.map((allocation) => allocation.id === item.id ? { ...allocation, destinationId: value } : allocation))} required options={data.equipment.map((equipment) => ({ value: equipment.id, label: equipment.label }))} /> : item.type === "maintenance" ? <SelectNative label="Maintenance" name={`destination-${item.id}`} value={item.destinationId} onChange={(value) => setAllocations((current) => current.map((allocation) => allocation.id === item.id ? { ...allocation, destinationId: value } : allocation))} required options={data.maintenance.map((record) => ({ value: record.id, label: record.label }))} /> : <div />}<Input label="Amount (PHP)" name={`allocationAmount-${item.id}`} value={item.amount} onChange={(event) => setAllocations((current) => current.map((allocation) => allocation.id === item.id ? { ...allocation, amount: event.target.value } : allocation))} placeholder={allocations.length === 1 ? "Full total" : "0.00"} required={allocations.length > 1} /><button type="button" disabled={allocations.length === 1} onClick={() => setAllocations((current) => current.filter((allocation) => allocation.id !== item.id))} aria-label={`Remove allocation ${index + 1}`} className="min-h-11 self-end rounded-control px-3 text-[var(--color-danger-text)] disabled:opacity-30">×</button></div>)}</div><SelectNative label="Receipt state" name="receiptStatus" options={[{ value: "missing", label: "Missing" }, { value: "not_required", label: "Not required" }]} /><Input label="Missing receipt explanation" name="receiptException" placeholder="Required when submitting without a receipt" /><Input label="Official receipt number" name="receiptNumber" /><Input label="Supplier invoice number" name="invoiceNumber" />{!reimbursement ? <label className="flex min-h-11 items-center gap-2 text-sm sm:col-span-2"><input type="checkbox" checked={ownerFunded} onChange={(event) => setOwnerFunded(event.target.checked)} /> Paid using owner funds</label> : null}{ownerFunded ? <SelectNative label="Owner / funding party" name="paidByUserId" required options={data.staff.filter((item) => item.role === "super_admin").map((item) => ({ value: item.id, label: item.name }))} /> : null}<label className="grid gap-1 text-xs font-semibold text-[var(--color-text-secondary)] sm:col-span-2"><span>Internal note</span><textarea name="internalNote" rows={2} className="rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] p-3 text-sm" /></label>{error ? <p role="alert" className="rounded-control bg-[var(--color-danger-bg)] p-3 text-sm text-[var(--color-danger-text)] sm:col-span-2">{error}</p> : null}<div className="rounded-control bg-[var(--color-warning-bg)] p-3 text-xs text-[var(--color-warning-text)] sm:col-span-2">Tax classification and receipt thresholds must be reviewed by a Philippine accountant before production use.</div></div><footer className="sticky bottom-0 flex flex-wrap justify-end gap-2 border-t border-[var(--color-border)] bg-[var(--color-surface)] p-5">{!reimbursement ? <button disabled={busy} data-submit="false" className="min-h-11 rounded-control border border-[var(--color-border)] px-4 text-sm font-semibold">Save draft</button> : null}<button disabled={busy} data-submit="true" className="min-h-11 rounded-control bg-[#FF5300] px-4 text-sm font-semibold text-white hover:bg-[#E64B00]">{busy ? "Saving..." : "Submit for review"}</button></footer></form></aside></>;
}

function Metric({ icon, title, value, detail, sub, tone = "neutral" }: { icon: ReactNode; title: string; value: string; detail: string; sub?: string; tone?: "neutral" | "warning" | "info" }) { return <article className="rounded-card border border-[var(--color-border)] bg-[var(--color-surface)] p-4"><div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[.04em] text-[var(--color-text-secondary)]"><span className={cn("[&>svg]:h-4 [&>svg]:w-4", tone === "warning" ? "text-[var(--color-warning-text)]" : tone === "info" ? "text-[var(--color-info-text)]" : "text-[#FF5300]")}>{icon}</span>{title}</div><p className="mt-3 font-display text-[28px] font-semibold tabular-nums">{value}</p><p className="mt-1 text-xs text-[var(--color-text-secondary)]">{detail}</p>{sub ? <p className="mt-1 text-[11px] text-[var(--color-text-muted)]">{sub}</p> : null}</article>; }
function Badge({ children, tone }: { children: ReactNode; tone: "neutral" | "info" | "success" | "warning" | "danger" }) { const style = { neutral: "bg-[var(--color-surface-muted)] text-[var(--color-text-secondary)]", info: "bg-[var(--color-info-bg)] text-[var(--color-info-text)]", success: "bg-[var(--color-success-bg)] text-[var(--color-success-text)]", warning: "bg-[var(--color-warning-bg)] text-[var(--color-warning-text)]", danger: "bg-[var(--color-danger-bg)] text-[var(--color-danger-text)]" }[tone]; return <span className={cn("inline-flex rounded-pill px-2.5 py-1 text-[11px] font-semibold", style)}>{children}</span>; }
function Detail({ label, value }: { label: string; value: string }) { return <div className="rounded-control border border-[var(--color-border)] bg-[var(--color-canvas)] p-3"><p className="text-[11px] font-semibold uppercase tracking-[.04em] text-[var(--color-text-secondary)]">{label}</p><p className="mt-1 text-sm font-medium">{value}</p></div>; }
function Section({ title, children }: { title: string; children: ReactNode }) { return <section className="mt-4 rounded-card border border-[var(--color-border)] p-4"><h3 className="font-display text-lg font-semibold">{title}</h3><div className="mt-3">{children}</div></section>; }
function Select({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: { value: string; label: string }[] }) { return <label className="grid gap-1 text-xs font-semibold text-[var(--color-text-secondary)]"><span>{label}</span><select value={value} onChange={(event) => onChange(event.target.value)} className="min-h-11 rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] px-3 text-sm text-[var(--color-text-primary)]">{options.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label>; }
function Input({ label, name, ...props }: { label: string; name: string } & React.InputHTMLAttributes<HTMLInputElement>) { return <label className="grid gap-1 text-xs font-semibold text-[var(--color-text-secondary)]"><span>{label}</span><input name={name} {...props} className="min-h-11 rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] px-3 text-sm text-[var(--color-text-primary)]" /></label>; }
function SelectNative({ label, name, options, required, value, onChange }: { label: string; name: string; options: { value: string; label: string }[]; required?: boolean; value?: string; onChange?: (value: string) => void }) { return <label className="grid gap-1 text-xs font-semibold text-[var(--color-text-secondary)]"><span>{label}</span><select name={name} required={required} value={value} onChange={onChange ? (event) => onChange(event.target.value) : undefined} className="min-h-11 rounded-control border border-[var(--color-border)] bg-[var(--color-surface)] px-3 text-sm text-[var(--color-text-primary)]"><option value="">Choose...</option>{options.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label>; }
function Empty({ filtered }: { filtered: boolean }) { return <div className="grid min-h-72 place-items-center p-8 text-center"><div><AlertTriangle className="mx-auto h-6 w-6 text-[var(--color-text-muted)]" /><h2 className="mt-3 font-display text-xl font-semibold">{filtered ? "No matching expenses" : "No expenses recorded"}</h2><p className="mt-1 text-sm text-[var(--color-text-secondary)]">{filtered ? "Adjust the search or filters." : "Record the first studio cost when it occurs."}</p></div></div>; }
function Th({ children, right }: { children: ReactNode; right?: boolean }) { return <th className={cn("px-4 py-3 font-medium", right && "text-right")}>{children}</th>; }
function Td({ children, right, mono }: { children: ReactNode; right?: boolean; mono?: boolean }) { return <td className={cn("border-t border-[var(--color-border)] px-4 py-4 align-top text-sm", right && "text-right", mono && "tabular-nums")}>{children}<style jsx>{`td :global(small){display:block;margin-top:.2rem;font-size:11px;color:var(--color-text-muted);max-width:15rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}`}</style></td>; }
function option(value: string) { return { value, label: value ? statusLabel(value) : "Any" }; }
function statusTone(status: string): "neutral" | "info" | "success" | "warning" | "danger" { if (["approved", "paid"].includes(status)) return "success"; if (["submitted", "needs_review", "changes_requested", "scheduled_for_payment"].includes(status)) return "warning"; if (["rejected", "voided"].includes(status)) return "danger"; if (status === "draft") return "neutral"; return "info"; }
function receiptTone(status: string): "neutral" | "info" | "success" | "warning" | "danger" { if (status === "verified") return "success"; if (["missing", "under_review"].includes(status)) return "warning"; if (status === "invalid") return "danger"; if (status === "attached") return "info"; return "neutral"; }
function manilaDate(value: string) { return new Intl.DateTimeFormat("en-PH", { dateStyle: "medium", timeZone: "Asia/Manila" }).format(new Date(`${value}T12:00:00+08:00`)); }
function dateTime(value: string | null) { return value ? new Intl.DateTimeFormat("en-PH", { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Manila" }).format(new Date(value)) : "Not recorded"; }
function comparison(current: number, previous: number) { if (previous === 0) return current === 0 ? "No change" : "New spending"; const change = Math.round((current - previous) / previous * 100); return `${change >= 0 ? "+" : ""}${change}%`; }
